<?php /** @var array $rows @var array $statuses @var string $selectedStatus @var bool $saved @var \Core\Security\Csrf $csrf @var string $frontController @var string $basePath */ ?>
<?php if($saved): ?><div class="flash-ok">Estimate lead updated.</div><?php endif; ?><div class="card"><form method="get" action="<?= e_attr($frontController) ?>" style="display:flex;gap:.5rem;align-items:end"><input type="hidden" name="p" value="/admin/landscaping/estimates"><label style="margin:0">Status<select name="status"><option value="">All</option><?php foreach($statuses as $status): ?><option value="<?= e_attr($status) ?>"<?= $selectedStatus===$status?' selected':'' ?>><?= e(ucwords(str_replace('-',' ',$status))) ?></option><?php endforeach; ?></select></label><button class="btn small">Filter</button><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/landscaping/estimates">Clear</a></form></div>
<?php if(!$rows): ?><div class="card"><p>No estimate requests match this filter.</p></div><?php endif; ?><?php foreach($rows as $row): $photos=json_decode((string)$row['photo_media_ids'],true)?:[]; ?><article class="card"><div style="display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap"><div><span class="badge<?= $row['status']==='new'?' warn':'' ?>"><?= e(ucwords(str_replace('-',' ',$row['status']))) ?></span><h2><?= e($row['name']) ?> · <?= e($row['service_interest']) ?></h2><p class="muted"><?= e($row['email']) ?> · <?= e($row['phone']) ?> · <?= e($row['created_at']) ?></p></div></div><table><tbody><tr><th>Property</th><td><?= e($row['property_type']) ?> · <?= e($row['lot_size']?:'Size unknown') ?></td><th>Schedule</th><td><?= e($row['schedule_preference']?:'Flexible') ?></td></tr><tr><th>Address</th><td><?= e($row['address'].', '.$row['city'].', '.$row['state'].' '.$row['zip']) ?></td><th>Budget</th><td><?= e($row['budget']?:'Not supplied') ?></td></tr></tbody></table><?php if($row['message']): ?><p><strong>Details:</strong><br><?= nl2br(e($row['message'])) ?></p><?php endif; ?><?php if($photos): ?><p><strong>Private property photos:</strong> <?php foreach($photos as $index=>$photoId): ?><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/landscaping/estimate-photo/<?= (int)$photoId ?>" target="_blank" rel="noopener">Photo <?= $index+1 ?></a> <?php endforeach; ?></p><?php endif; ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div class="grid2"><label>Status<select name="status"><?php foreach($statuses as $status): ?><option value="<?= e_attr($status) ?>"<?= $row['status']===$status?' selected':'' ?>><?= e(ucwords(str_replace('-',' ',$status))) ?></option><?php endforeach; ?></select></label><label>Internal notes<textarea name="admin_notes" rows="3" maxlength="5000"><?= e($row['admin_notes']??'') ?></textarea></label></div><button class="btn small">Save lead</button></form></article><?php endforeach; ?>
